import{o as n,c as i,a0 as s,j as o,t as r,p as l}from"./chunks/framework.L_oL6aia.js";const d={class:"rock-card-contact",style:{"max-width":"600px",margin:"3rem auto 1rem auto"}},c={class:"rock-copy-email-wrapper card-contact"},m=JSON.parse('{"title":"Beast of Burden: User Manual","description":"","frontmatter":{},"headers":[],"relativePath":"beast-of-burden.md","filePath":"beast-of-burden.md"}'),u={name:"beast-of-burden.md"},b=Object.assign(u,{setup(p){const a=l("Copy Email");function t(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),a.value="Copied!",setTimeout(function(){a.value="Copy Email"},2e3)}return(h,e)=>(n(),i("div",null,[e[3]||(e[3]=s(`<h1 id="beast-of-burden-user-manual" tabindex="-1">Beast of Burden: User Manual <a class="header-anchor" href="#beast-of-burden-user-manual" aria-label="Permalink to &quot;Beast of Burden: User Manual&quot;">​</a></h1><p><strong>Version 1.0.0 · Virtual Stompbox &amp; Amplifier Simulation</strong></p><p>This manual provides a detailed description of the design philosophy, signal chain architecture, control parameters, and recommended presets for the <strong>Beast of Burden</strong> amplifier emulation and vintage FX suite.</p><img src="/bob.png" alt="Beast of Burden Plugin GUI" style="max-height:280px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:4px;"><hr><h2 id="_1-design-philosophy-the-100w-tube-crunch-lead-beast" tabindex="-1">1. Design Philosophy: The 100W Tube Crunch &amp; Lead Beast <a class="header-anchor" href="#_1-design-philosophy-the-100w-tube-crunch-lead-beast" aria-label="Permalink to &quot;1. Design Philosophy: The 100W Tube Crunch &amp; Lead Beast&quot;">​</a></h2><p><strong>Beast of Burden</strong> is a dedicated amplifier simulation and vintage effects suite pairing an authentic 100W 6L6 tube amplifier architecture with the signature <strong>Stones &#39;78 Vintage Dual FX Suite</strong> (Phase &#39;78 optical phaser and analog tape slapback delay) and a studio-recorded <strong>Pacific Woodworks 1x12 Thiele cabinet with an Electro-Voice EVM-12L speaker</strong>.</p><h3 id="the-sound-of-studio-stage" tabindex="-1">The Sound of Studio &amp; Stage <a class="header-anchor" href="#the-sound-of-studio-stage" aria-label="Permalink to &quot;The Sound of Studio &amp; Stage&quot;">​</a></h3><p>Inspired by the high-headroom, cascaded-gain rigs that defined legendary late &#39;70s and early &#39;80s rock records:</p><ul><li><strong>Hyper-Fast Attack &amp; Punch:</strong> Massive power supply headroom, four 6L6 power tubes, and the ultra-efficient 200W Electro-Voice EVM-12L speaker.</li><li><strong>Liquid Modulation &amp; Dimension:</strong> Running guitars through vintage optical phasing and tape slapback echo before hitting the tube preamp.</li><li><strong>The Iconic 5-Band Graphic EQ:</strong> Sculpting mid attack (2.2 kHz) and vocal presence (750 Hz) while clearing low-mid mud (240 Hz).</li></ul><hr><h2 id="_2-3-channel-amplifier-architecture" tabindex="-1">2. 3-Channel Amplifier Architecture <a class="header-anchor" href="#_2-3-channel-amplifier-architecture" aria-label="Permalink to &quot;2. 3-Channel Amplifier Architecture&quot;">​</a></h2><p>Beast of Burden features a straightforward 3-way channel selector covering the entire tonal spectrum:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Channel Mode</th><th style="text-align:left;">Tone Character</th><th style="text-align:left;">Ideal Applications</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>CLEAN</code></strong></td><td style="text-align:left;">Pristine clean tone with natural tube compression, wide dynamic headroom and smooth, chimey highs.</td><td style="text-align:left;">Open-G chord balance, funk chops, soul ballads and dynamic fingerpicking.</td></tr><tr><td style="text-align:left;"><strong><code>CRUNCH</code></strong></td><td style="text-align:left;">Organic edge-of-breakup with a solid low-end body, punchy mids and immediate tactile response to pick attack.</td><td style="text-align:left;">Rhythmic rock riffs, classic Stones overdrive, blues solos and chord crunch.</td></tr><tr><td style="text-align:left;"><strong><code>LEAD</code></strong></td><td style="text-align:left;">Searing high-gain tube saturation with rich harmonic sustain, liquid soloing feel and focused low end.</td><td style="text-align:left;">Singing lead lines, heavy riffs, slide guitar and sustained soloing.</td></tr></tbody></table><hr><h2 id="_3-complete-control-guide" tabindex="-1">3. Complete Control Guide <a class="header-anchor" href="#_3-complete-control-guide" aria-label="Permalink to &quot;3. Complete Control Guide&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ GUITAR INPUT ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ PHASE &#39;78 ]  ───►  [ SLAPBACK DELAY ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ 100W 6L6 TUBE PREAMP (Clean / Crunch / Lead) ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ 5-BAND GRAPHIC EQ ]  ───►  [ EVM-12L CABINET SIMULATION ]</span></span>
<span class="line"><span>       │</span></span>
<span class="line"><span>       ▼</span></span>
<span class="line"><span> [ MASTER OUTPUT ]  ───►  [ STEREO OUT ]</span></span></code></pre></div><h3 id="🎛️-1-main-amplifier-controls" tabindex="-1">🎛️ 1. Main Amplifier Controls <a class="header-anchor" href="#🎛️-1-main-amplifier-controls" aria-label="Permalink to &quot;🎛️ 1. Main Amplifier Controls&quot;">​</a></h3><ul><li><strong><code>GAIN</code> (Volume / Drive):</strong> Sets input signal drive into the amplifier (<code>1.0</code> = -9 dB, <code>7.0</code> = 0 dB Unity Gain, <code>10.0</code> = +4.5 dB boost).</li><li><strong><code>MASTER</code>:</strong> Clean analog output volume (<code>1.0</code> = -36 dB bedroom volume, <code>7.0</code> = 0 dB Unity Gain, <code>10.0</code> = +18 dB boost).</li><li><strong><code>CHANNEL SELECTOR</code>:</strong> 3-position rotary selector switching between <code>CLEAN</code>, <code>CRUNCH</code>, and <code>LEAD</code>.</li></ul><hr><h3 id="🎚️-2-5-band-graphic-equalizer" tabindex="-1">🎚️ 2. 5-Band Graphic Equalizer <a class="header-anchor" href="#🎚️-2-5-band-graphic-equalizer" aria-label="Permalink to &quot;🎚️ 2. 5-Band Graphic Equalizer&quot;">​</a></h3><p>An authentic recreation of the classic Mesa/Boogie active slider EQ with an independent <strong><code>EQ IN</code></strong> toggle and status LED:</p><ul><li><strong><code>80 Hz</code> (±12 dB):</strong> Deep sub-bass thump and cab resonance.</li><li><strong><code>240 Hz</code> (±12 dB):</strong> Low-mid boxiness control. Cutting clears mud.</li><li><strong><code>750 Hz</code> (±12 dB):</strong> Midrange punch and vocal bark.</li><li><strong><code>2200 Hz / 2.2 kHz</code> (±12 dB):</strong> The attack frequency! Delivers pick snap and chord bite.</li><li><strong><code>6600 Hz / 6.6 kHz</code> (±12 dB):</strong> Smooth air and chime characteristic of the EVM-12L speaker.</li></ul><hr><h3 id="🌀-3-stones-78-vintage-dual-fx-suite" tabindex="-1">🌀 3. Stones &#39;78 Vintage Dual FX Suite <a class="header-anchor" href="#🌀-3-stones-78-vintage-dual-fx-suite" aria-label="Permalink to &quot;🌀 3. Stones &#39;78 Vintage Dual FX Suite&quot;">​</a></h3><p>Integrated directly before the preamp stage, replicating the exact pedalboard signal flow used on classic records:</p><h4 id="phase-78-mxr-phase-100-style-optical-phaser" tabindex="-1"><strong>Phase &#39;78 (MXR Phase 100 Style Optical Phaser)</strong> <a class="header-anchor" href="#phase-78-mxr-phase-100-style-optical-phaser" aria-label="Permalink to &quot;**Phase &#39;78 (MXR Phase 100 Style Optical Phaser)**&quot;">​</a></h4><ul><li><strong><code>PHASE &#39;78 Toggle &amp; Amber LED</code>:</strong> Activates or bypasses the phaser with 0% CPU consumption.</li><li><strong><code>SPEED</code> (<code>0.10 Hz</code> to <code>8.00 Hz</code>):</strong> Controls the LFO modulation rate with live dynamic numerical display.</li><li><strong><code>INTENS</code> (<code>0%</code> to <code>100%</code>):</strong> Controls sweep depth and vocal resonance.</li></ul><h4 id="slapback-delay-analog-tape-echo" tabindex="-1"><strong>Slapback Delay (Analog Tape Echo)</strong> <a class="header-anchor" href="#slapback-delay-analog-tape-echo" aria-label="Permalink to &quot;**Slapback Delay (Analog Tape Echo)**&quot;">​</a></h4><ul><li><strong><code>DELAY Toggle &amp; Red LED</code>:</strong> Activates or bypasses the tape echo.</li><li><strong><code>TIME</code> (<code>20 ms</code> to <code>300 ms</code>):</strong> Sets delay time with dynamic millisecond readout. Default: <code>110 ms</code> (Keith&#39;s classic slapback sweet spot).</li><li><strong><code>REPEATS</code> (<code>0%</code> to <code>65%</code>):</strong> Controls tape feedback.</li><li><strong><code>MIX</code> (<code>0%</code> to <code>50%</code>):</strong> Controls wet/dry balance.</li></ul><hr><h3 id="🔊-4-pacific-woodworks-1x12-evm-12l-cabinet-simulation" tabindex="-1">🔊 4. Pacific Woodworks 1x12 EVM-12L Cabinet Simulation <a class="header-anchor" href="#🔊-4-pacific-woodworks-1x12-evm-12l-cabinet-simulation" aria-label="Permalink to &quot;🔊 4. Pacific Woodworks 1x12 EVM-12L Cabinet Simulation&quot;">​</a></h3><p>The Pacific Woodworks 1x12 (Thiele ported) cabinet loaded with an Electro-Voice EVM-12L 200W speaker delivers massive power handling, transparent mids, and punchy, tight bass. The <strong><code>CABINET</code></strong> selector offers 6 studio microphone placements plus a bypass option:</p><ol><li><strong><code>SM57 SweetSpot</code>:</strong> Shure SM57 on cap-edge — balanced attack, rich mids and solid punch.</li><li><strong><code>SM57 Warm</code>:</strong> Shure SM57 on outer cone — deep lows, smooth highs and warm textures.</li><li><strong><code>SM57 Direct</code>:</strong> Shure SM57 on center — razor-sharp articulation and immediate bite.</li><li><strong><code>SM57 BassPort</code>:</strong> Shure SM57 on the Thiele port — extended low-end thump (80–100 Hz).</li><li><strong><code>U87 Studio</code>:</strong> Neumann U87Ai large diaphragm condenser — high fidelity, wide dynamic range and open 3D air.</li><li><strong><code>U87 Warm</code>:</strong> Neumann U87Ai in warm zone — dense harmonic body without top-end harshness.</li><li><strong><code>Bypass IR</code>:</strong> Disables internal cabinet simulation for pairing with external third-party IR loaders.</li></ol><hr><h3 id="🖼️-5-standby-custom-tolex-skinning" tabindex="-1">🖼️ 5. Standby &amp; Custom Tolex Skinning <a class="header-anchor" href="#🖼️-5-standby-custom-tolex-skinning" aria-label="Permalink to &quot;🖼️ 5. Standby &amp; Custom Tolex Skinning&quot;">​</a></h3><ul><li><strong><code>STANDBY</code>:</strong> Mutes audio output and reduces neural CPU processing to <strong>0%</strong> immediately.</li><li><strong>Drag-and-Drop Backgrounds:</strong> Drag any <code>.jpg</code>, <code>.jpeg</code>, or <code>.png</code> image directly onto the plugin window from your file manager to customize its visual skin in real time.</li></ul><hr><h2 id="_4-recommended-track-presets-dial-in-guides" tabindex="-1">4. Recommended Track Presets &amp; Dial-In Guides <a class="header-anchor" href="#_4-recommended-track-presets-dial-in-guides" aria-label="Permalink to &quot;4. Recommended Track Presets &amp; Dial-In Guides&quot;">​</a></h2><p>Here are studio-tested dial-in settings for iconic guitar tones:</p><h3 id="🌟-preset-1-beast-of-burden-the-signature-liquid-phase-tone" tabindex="-1">🌟 Preset 1: &quot;Beast of Burden&quot; (The Signature Liquid Phase Tone) <a class="header-anchor" href="#🌟-preset-1-beast-of-burden-the-signature-liquid-phase-tone" aria-label="Permalink to &quot;🌟 Preset 1: &quot;Beast of Burden&quot; (The Signature Liquid Phase Tone)&quot;">​</a></h3><ul><li><strong>Channel:</strong> <code>CLEAN</code></li><li><strong>Gain:</strong> <code>7.0</code> | <strong>Master:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: 0dB</code> | <code>240Hz: -2.0dB</code> | <code>750Hz: +2.0dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +1.5dB</code></li><li><strong>Phase &#39;78:</strong> <code>ON</code> | Speed: <code>0.80 Hz</code> | Intensity: <code>60%</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>110 ms</code> | Repeats: <code>20%</code> | Mix: <code>25%</code></li><li><strong>Cabinet:</strong> <code>SM57 SweetSpot</code> (or <code>SM57 Warm</code>)</li></ul><h3 id="⚡-preset-2-start-me-up-tattoo-you-crunch-open-g-riff-power" tabindex="-1">⚡ Preset 2: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Open-G Riff Power) <a class="header-anchor" href="#⚡-preset-2-start-me-up-tattoo-you-crunch-open-g-riff-power" aria-label="Permalink to &quot;⚡ Preset 2: &quot;Start Me Up&quot; / &quot;Tattoo You Crunch&quot; (Open-G Riff Power)&quot;">​</a></h3><ul><li><strong>Channel:</strong> <code>CRUNCH</code></li><li><strong>Gain:</strong> <code>7.5</code> | <strong>Master:</strong> <code>7.5</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +1.5dB</code> | <code>240Hz: -3.0dB</code> | <code>750Hz: +2.5dB</code> | <code>2.2kHz: +4.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Phase &#39;78:</strong> <code>OFF</code></li><li><strong>Slapback Delay:</strong> <code>OFF</code> (or <code>ON</code> with Mix @ <code>12%</code> for studio depth)</li><li><strong>Cabinet:</strong> <code>SM57 Warm</code></li></ul><h3 id="👑-preset-3-classic-rock-lead-solo-singing-tube-sustain" tabindex="-1">👑 Preset 3: &quot;Classic Rock Lead &amp; Solo&quot; (Singing Tube Sustain) <a class="header-anchor" href="#👑-preset-3-classic-rock-lead-solo-singing-tube-sustain" aria-label="Permalink to &quot;👑 Preset 3: &quot;Classic Rock Lead &amp; Solo&quot; (Singing Tube Sustain)&quot;">​</a></h3><ul><li><strong>Channel:</strong> <code>LEAD</code></li><li><strong>Gain:</strong> <code>8.0</code> | <strong>Master:</strong> <code>7.0</code></li><li><strong>5-Band Graphic EQ:</strong> <code>80Hz: +2.0dB</code> | <code>240Hz: -1.5dB</code> | <code>750Hz: +3.5dB</code> | <code>2.2kHz: +3.0dB</code> | <code>6.6kHz: +2.0dB</code></li><li><strong>Slapback Delay:</strong> <code>ON</code> | Time: <code>140 ms</code> | Repeats: <code>30%</code> | Mix: <code>25%</code></li><li><strong>Cabinet:</strong> <code>SM57 Direct</code> (or <code>U87 Studio</code>)</li></ul><hr><h2 id="_5-standalone-audio-configuration" tabindex="-1">5. Standalone Audio Configuration <a class="header-anchor" href="#_5-standalone-audio-configuration" aria-label="Permalink to &quot;5. Standalone Audio Configuration&quot;">​</a></h2><p>When running Beast of Burden as a standalone application on Windows:</p><ol><li><strong>Audio Device Type:</strong> Select <strong>ASIO</strong> (essential for ultra-low latency).</li><li><strong>Device:</strong> Choose your audio interface&#39;s native ASIO driver.</li><li><strong>Smart Input Detection:</strong> Beast of Burden automatically senses your active guitar input (Input 1 or Input 2) and sends 100% full-level mono audio to both stereo outputs without signal loss.</li><li><strong>Sample Rate:</strong> Set to <strong>48000 Hz</strong> (48 kHz) for optimal neural inference.</li><li><strong>Buffer Size:</strong> Set to <strong>128 samples</strong> (2.7 ms) or <strong>256 samples</strong> (5.3 ms) for seamless real-time monitoring.</li></ol><hr><h2 id="_6-technical-specifications" tabindex="-1">6. Technical Specifications <a class="header-anchor" href="#_6-technical-specifications" aria-label="Permalink to &quot;6. Technical Specifications&quot;">​</a></h2><ul><li><strong>Formats:</strong> VST3 (64-bit) and Standalone Windows Executable (.exe).</li><li><strong>Sample Rates:</strong> 44.1 kHz, 48 kHz, 88.2 kHz, 96 kHz (Internal neural engine handles multi-rate inference).</li><li><strong>DSP Framework:</strong> JUCE 9 + Eigen + Neural Amp Modeler (NAM) C++ Core.</li><li><strong>Instruction Set:</strong> Full SIMD AVX/AVX2 Vectorization.</li><li><strong>Developer:</strong> Main St Audio Labs.</li></ul><hr>`,54)),o("div",d,[e[1]||(e[1]=o("div",{class:"rock-card-contact-title"},"Questions or Early Access Inquiries?",-1)),e[2]||(e[2]=o("p",{class:"rock-card-contact-desc"},"We love hearing from guitarists and mixing engineers. Send us your questions or suggestions.",-1)),o("div",c,[e[0]||(e[0]=o("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),o("button",{class:"rock-copy-btn",onClick:t},r(a.value),1)])])]))}});export{m as __pageData,b as default};
